#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
#
# resolve-target.sh: classify the review-pr argument into ONE review target (#3892).
#
# Usage: resolve-target.sh [ARGUMENTS...]
# Prints exactly one JSON object on stdout, exit 0:
#   {"kind":"pr","number":"123","source":"argument|url|env|current-branch"}
#   {"kind":"range","base":"origin/main","head":"origin/qa","op":"..."}
#   {"kind":"ref","ref":"feature-branch"}
#   {"kind":"ask","reason":"..."}
#
# kind=ask means STOP and ask the user. This script never substitutes HEAD or
# the current checkout for a target the user named: before #3892 the skill
# treated any non-numeric argument as "no argument", fell back to the current
# branch, and reviewed an unrelated change without asking.
#
# Precedence when free text carries several candidates: exactly one ref range
# wins (it is the most specific target), then exactly one PR number or URL,
# then exactly one token that resolves to a commit. Anything ambiguous asks.
# Set ORK_RESOLVE_TARGET_OFFLINE=1 to skip the gh lookup (tests).

set -euo pipefail
set -f # tokens like "#1837)" must never glob

REF_CHARS='^[A-Za-z0-9_/@~^{}.+-]+$'

json_str() {
  local s=${1//\\/\\\\}
  s=${s//\"/\\\"}
  printf '"%s"' "$s"
}

emit_ask() {
  printf '{"kind":"ask","reason":%s}\n' "$(json_str "$1")"
  exit 0
}

emit_pr() {
  printf '{"kind":"pr","number":%s,"source":%s}\n' "$(json_str "$1")" "$(json_str "$2")"
  exit 0
}

# A usable ref name: allowed characters, no leading dash (option injection),
# no leading or trailing dot.
valid_ref_name() {
  local r=$1
  [[ -n "$r" && "$r" =~ $REF_CHARS && "$r" != -* && "$r" != .* && "$r" != *. ]]
}

# rev-parse --quiet prints nothing for an unknown ref; the emptiness test is
# the verdict, so its exit status is deliberately not the one that decides.
resolves_to_commit() {
  local sha
  if sha=$(git rev-parse --verify --quiet "$1^{commit}"); then
    [[ -n "$sha" ]]
  else
    return 1
  fi
}

# Space-separated sets: tokens never contain spaces, and plain strings avoid
# the empty-array-under-set-u trap of macOS bash 3.2.
has_word() { case " $1 " in *" $2 "*) return 0 ;; esac; return 1; }
count_words() { set -- $1; echo $#; }
first_word() { set -- $1; echo "${1:-}"; }

# A PR URL names a repository, and keeping only the number let a URL from a
# DIFFERENT repo review the same-numbered PR in this checkout. Downstream `gh
# pr` calls are repo-scoped, so the two paths below are compared and a mismatch
# asks rather than reviewing the wrong change (the whole point of #3892).
url_repo_path() { # host/owner/repo of a PR URL, empty when it does not parse
  printf '%s' "$1" | sed -nE 's|^https?://([^/]+)/([^/]+)/([^/]+)/(pull\|pulls\|merge_requests)/[0-9]+.*$|\1/\2/\3|p'
}
local_repo_path() { # host/owner/repo of origin, empty when there is no remote
  # No origin (a bare dir, a fresh init) is a valid answer, not an error: the
  # comparison is then skipped rather than blocking a legitimate URL.
  if ! u=$(git remote get-url origin 2>&1); then return 0; fi
  [ -n "$u" ] || return 0
  u=${u%.git}
  case "$u" in
    ssh://git@*) u=${u#ssh://git@} ;;
    git@*) u=${u#git@}; u=${u/://} ;;
    https://*) u=${u#https://} ;;
    http://*) u=${u#http://} ;;
  esac
  printf '%s' "$u"
}
lower_str() { printf '%s' "$1" | tr '[:upper:]' '[:lower:]'; }

pr_numbers=""
pr_source=""
ranges=""
ref_candidates=""

for tok in $*; do
  # Strip wrapping punctuation from free text: "(#1837," becomes "#1837".
  while [[ "$tok" == [\(\[\"\']* ]]; do tok=${tok:1}; done
  while [[ "$tok" == *[\)\]\"\',\;:] ]]; do tok=${tok%?}; done
  if [[ -z "$tok" ]]; then continue; fi

  if [[ "$tok" =~ ^https?://[^[:space:]]+/(pull|pulls|merge_requests)/([0-9]+)([/?#].*)?$ ]]; then
    n=${BASH_REMATCH[2]}
    url_repo=$(url_repo_path "$tok")
    local_repo=$(local_repo_path)
    if [[ -n "$url_repo" && -n "$local_repo" ]] &&
       [[ "$(lower_str "$url_repo")" != "$(lower_str "$local_repo")" ]]; then
      emit_ask "the URL names $url_repo but this checkout is $local_repo; run review-pr from that repository (reviewing PR $n here would be a different change)"
    fi
    if ! has_word "$pr_numbers" "$n"; then pr_numbers="$pr_numbers $n"; pr_source=${pr_source:-url}; fi
    continue
  fi
  if [[ "$tok" =~ ^#?([0-9]+)$ ]]; then
    n=${BASH_REMATCH[1]}
    if ! has_word "$pr_numbers" "$n"; then pr_numbers="$pr_numbers $n"; pr_source=${pr_source:-argument}; fi
    continue
  fi
  if [[ "$tok" == *..* ]]; then
    if [[ "$tok" == *...* ]]; then op='...'; else op='..'; fi
    base=${tok%%"$op"*}
    head=${tok#*"$op"}
    if valid_ref_name "$base" && valid_ref_name "$head" && [[ "$head" != *..* ]]; then
      if ! has_word "$ranges" "$tok"; then ranges="$ranges $tok"; fi
    fi
    continue
  fi
  if valid_ref_name "$tok"; then
    if ! has_word "$ref_candidates" "$tok"; then ref_candidates="$ref_candidates $tok"; fi
  fi
done

n_ranges=$(count_words "$ranges")
if (( n_ranges > 1 )); then
  emit_ask "several ref ranges in the argument:$ranges"
fi
if (( n_ranges == 1 )); then
  range=$(first_word "$ranges")
  if [[ "$range" == *...* ]]; then op='...'; else op='..'; fi
  base=${range%%"$op"*}
  head=${range#*"$op"}
  for side in "$base" "$head"; do
    if ! resolves_to_commit "$side"; then
      emit_ask "ref range side '$side' does not resolve to a commit here (fetch it first, or give a PR number)"
    fi
  done
  printf '{"kind":"range","base":%s,"head":%s,"op":%s}\n' "$(json_str "$base")" "$(json_str "$head")" "$(json_str "$op")"
  exit 0
fi

n_prs=$(count_words "$pr_numbers")
if (( n_prs > 1 )); then
  emit_ask "several PR numbers in the argument:$pr_numbers"
fi
if (( n_prs == 1 )); then
  emit_pr "$(first_word "$pr_numbers")" "$pr_source"
fi

if [[ -n "${ref_candidates// /}" ]]; then
  resolved=""
  for r in $ref_candidates; do
    if resolves_to_commit "$r"; then resolved="$resolved $r"; fi
  done
  n_resolved=$(count_words "$resolved")
  if (( n_resolved == 1 )); then
    printf '{"kind":"ref","ref":%s}\n' "$(json_str "$(first_word "$resolved")")"
    exit 0
  fi
  if (( n_resolved > 1 )); then
    emit_ask "several refs in the argument:$resolved"
  fi
  emit_ask "'$*' is not a PR number, PR URL, ref range, or a ref that resolves here"
fi

# No argument at all.
env_url=${ORCHESTKIT_PR_URL:-}
if [[ "$env_url" =~ /(pull|pulls|merge_requests)/([0-9]+)/?$ ]]; then
  emit_pr "${BASH_REMATCH[2]}" "env"
fi

if [[ "${ORK_RESOLVE_TARGET_OFFLINE:-0}" != "1" ]] && command -v gh >/dev/null; then
  # A branch without a PR makes gh exit non-zero with an error message. That
  # is the normal "ask" case, handled by the fall-through below with the
  # reason stated, so the failure is branched on rather than ignored.
  if current=$(gh pr view --json number -q .number 2>&1) && [[ "$current" =~ ^[0-9]+$ ]]; then
    emit_pr "$current" "current-branch"
  fi
fi

emit_ask "no argument, and the current branch has no open PR"
